# Makes the UAT 98 regression scripts from UAT 97's (work/cp97), changing only: check 0 (the build is now published UAT 97
# + the build name + the CP-72 hang edits and block), the references (CP-78's patched copies, read from work/cp97), the output
# folder (tickets/CP-72-evidence/uat98) and JSON names, checks75's reference name (UAT 94 renamed to UAT 98), and in checks94
# the power may run up to 1.5 s past UAT 93's + the title (the kitten's longer hang). checks96 (UAT 96's hang) is replaced by
# checks98, which compares the new hang with UAT 97's (= UAT 96's hang) and checks that one switch gives it back exactly.
from pathlib import Path
import re
p=Path(__file__).parent;S=p.parent/'cp97'
C0=(" {const S=fs.readFileSync(src,'utf8');let B=fs.readFileSync(path.resolve(__dirname,'../cp97/release.html'),'utf8');let m=[1];"
 "if(require('crypto').createHash('sha256').update(B).digest('hex')!=='9d3f975a51b5382a69f0407e7ff46110de571ede4a1b62a6975c727626c87899')m=[];"
 "const E=JSON.parse(fs.readFileSync(path.join(__dirname,'edits.json'),'utf8'));for(const [a,b] of E.edits){if(B.split(a).length!==2)m=[];B=B.split(a).join(b);}"
 "const i=B.lastIndexOf('</script>');B=B.slice(0,i)+fs.readFileSync(path.join(__dirname,'cp72-crazy.js'),'utf8')+String.fromCharCode(10)+B.slice(i);\n"
 "  check('0 the build is published UAT 97 + build name + the CP-72 hang edits and block (everything else of UAT 97 unchanged)',S===B&&m.length===1);}\n")
for f in ('checks97.cjs','checks75-on97.cjs','checks94-on97.cjs','checks93-on97.cjs','checks92-on97.cjs','checks72-on97.cjs','checks71-on97.cjs','checks64-on97.cjs'):
    s=(S/f).read_text(encoding='utf-8');o='checks97-on98.cjs' if f=='checks97.cjs' else f.replace('on97','on98')
    s,n=re.subn(r" \{const S=fs\.readFileSync\(src,'utf8'\);.*?check\('0 [^\n]*\n",lambda m:C0,s,count=1,flags=re.S);assert n==1,f
    s=re.sub(r"path\.join\(__dirname,'(ref78-[a-z0-9-]+\.html)'\)",r"path.join(__dirname,'../cp97/\1')",s)
    s=re.sub(r"path\.resolve\(__dirname,DEV\?'(ref78-[a-z0-9-]+\.html)':'(ref78-[a-z0-9-]+\.html)'\)",r"path.resolve(__dirname,DEV?'../cp97/\1':'../cp97/\2')",s)
    if f=='checks75-on97.cjs':
        s=s.replace('named97','named98').replace("const BUILD = '2026.11.18 UAT 97';","const BUILD = '2026.11.18 UAT 98';").replace('the UAT 97 build name','the UAT 98 build name')
    if f=='checks94-on97.cjs':
        a="len:a.len>=b.len+LEAD-.1&&a.len<=b.len+LEAD+1.05,";assert s.count(a)==1;s=s.replace(a,"len:a.len>=b.len+LEAD-.1&&a.len<=b.len+LEAD+1.5,")
    s=s.replace("CP-78-evidence/uat97","CP-72-evidence/uat98").replace("'../../tickets/CP-78-evidence/uat'","'../../tickets/CP-72-evidence/uat'")
    s=s.replace(f.replace('.cjs','.json'),o.replace('.cjs','.json'))
    assert 'CP-78-evidence' not in s and 'CP-72-evidence' in s,f
    left=re.findall(r"['\"](ref78-[^'\"]+)['\"]",s);assert not left,(f,left)
    s="// UAT 98 (CP-72 hang): generated by work/cp98/gen-checks.py from work/cp97/"+f+".\n"+s
    (p/o).write_text(s,encoding='utf-8');print(o)
